def parse_kv(text):
    cfg = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, value = line.split("=", 1)
        cfg[key] = value
    return cfg

alt:
def parse_kv(text):
    pairs = [l.split("=", 1) for l in text.splitlines() if l.strip() and not l.strip().startswith("#")]
    return {k: v for k, v in pairs}
